/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field lifeTo.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableLifeTo extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, lifeTo);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Date);
    RetailInventTable retailInventTable;
    while select lifeTo from retailInventTable
        group by lifeTo
    {
        ret.add(retailInventTable.lifeTo);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, lifeTo));
    qbr.value(queryValue(_value));
}
